  isDragging = true;
  // Start throttled updates
  throttleCursorUpdates();
}

// Mouse Up Event
function handleMouseUp() {
  isDragging = false;
  // Send final position immediately
  sendCursorUpdate(getCurrentCursorPosition());
}

