// ... (Use pinMap in your D3 chart)
```

**Alternative: Custom Serialization:**

For more complex scenarios or if you want finer control over the serialization format, you could create your own serialization and deserialization functions:

```javascript
function serializeMap(map) {
  return Array.from(map.entries()).map(([key, value]) => ({ key, value }));
}

function deserializeMap(array) {
  const map = new Map();
  array.forEach(({ key, value }) => map.set(key, value));
  return map;
}
```



